import { Suspense } from 'react'
import { ProductGrid } from './ProductGrid'
import { ProductGridSkeleton } from './ProductSkeleton'

export default function Home() {
  return (
    <main>
      <h1>Products</h1>
      <Suspense fallback={<ProductGridSkeleton />}>
        <ProductGrid />
      </Suspense>
    </main>
  )
}

import Link from 'next/link'
import { products } from '@/lib/products'

export function ProductGrid() {
  return (
    <div className="product-grid">
      {products.map((product) => (
        <Link
          key={product.slug}
          href={`/product/${product.slug}`}
          className="product-card"
        >
          <div
            className="product-image"
            style={{ backgroundColor: product.color }}
          />
          <h2>{product.name}</h2>
          <p>${product.price}</p>
        </Link>
      ))}
    </div>
  )
}

export function ProductGridSkeleton() {
  return (
    <div className="product-grid">
      {Array.from({ length: 4 }).map((_, i) => (
        <div key={i} className="product-card">
          <div className="product-image skeleton-image" />
          <div className="skeleton-text" />
          <div className="skeleton-text short" />
        </div>
      ))}
    </div>
  )
}

import { Suspense } from 'react'
import Link from 'next/link'
import { getProduct, products } from '@/lib/products'
import { notFound } from 'next/navigation'

async function ProductDetails({ slug }: { slug: string }) {
  await new Promise((resolve) => setTimeout(resolve, 100))
  const product = getProduct(slug)
  if (!product) notFound()

  return (
    <div className="product-info">
      <h1>{product.name}</h1>
      <p className="product-price">${product.price}</p>
      <p className="product-description">{product.description}</p>
    </div>
  )
}

function DetailsSkeleton() {
  return (
    <div className="product-info">
      <div className="skeleton-text large" />
      <div className="skeleton-text short" />
      <div className="skeleton-text" />
    </div>
  )
}

export default async function ProductPage({
  params,
}: {
  params: Promise<{ slug: string }>
}) {
  const { slug } = await params
  const product = products.find((p) => p.slug === slug)
  if (!product) notFound()

  return (
    <div>
      <Link href="/" className="back-link">
        ← Back to products
      </Link>
      <div className="product-detail">
        <div
          className="product-hero"
          style={{ backgroundColor: product.color }}
        />
        <Suspense fallback={<DetailsSkeleton />}>
          <ProductDetails slug={slug} />
        </Suspense>
      </div>
    </div>
  )
}

export type Product = {
  slug: string
  name: string
  description: string
  price: number
  color: string
}

export const products: Product[] = [
  {
    slug: 'classic-sneakers',
    name: 'Classic Sneakers',
    description: 'Timeless design meets everyday comfort.',
    price: 89,
    color: '#4F46E5',
  },
  {
    slug: 'leather-backpack',
    name: 'Leather Backpack',
    description: 'Handcrafted from premium full-grain leather.',
    price: 129,
    color: '#059669',
  },
  {
    slug: 'wireless-headphones',
    name: 'Wireless Headphones',
    description: 'Crystal-clear audio with active noise cancellation.',
    price: 199,
    color: '#DC2626',
  },
  {
    slug: 'cotton-hoodie',
    name: 'Cotton Hoodie',
    description: 'Ultra-soft organic cotton blend for all-day wear.',
    price: 65,
    color: '#D97706',
  },
]

export function getProduct(slug: string): Product | undefined {
  return products.find((p) => p.slug === slug)
}

