/**
 * Stable `view-transition-name` for a product's image.
 *
 * The grid thumbnail and the detail hero must resolve to the exact same name for
 * React to pair them up and morph one into the other, so both render sites read
 * it from here. The replace keeps the result a valid CSS custom-ident even if a
 * slug later contains characters that aren't ident-safe.
 */
export function productImageTransitionName(slug: string): string {
  return `product-image-${slug.replace(/[^a-zA-Z0-9_-]/g, '-')}`
}

