import { ViewTransition } from 'react'
import type { ReactNode } from 'react'

/**
 * The transition types we tag navigations with. `<Link transitionTypes={...}>`
 * forwards these to React's `addTransitionType` from inside the navigation's
 * `startTransition`, which lets the classes below pick a direction per route
 * change instead of hard-coding one animation for every navigation.
 */
export const NAV_FORWARD = 'nav-forward'
export const NAV_BACK = 'nav-back'

/**
 * Entering page: forward navigations come in from the right, back navigations
 * from the left. `default` covers navigations that carry no type at all — most
 * notably the browser's own back/forward buttons, which go through the router
 * without passing a <Link>. Those get a plain fade rather than a slide that
 * might point the wrong way.
 */
const enterClass = {
  [NAV_FORWARD]: 'page-enter-forward',
  [NAV_BACK]: 'page-enter-back',
  default: 'page-fade-in',
}

/** Exiting page: mirrors `enterClass` so the two pages travel the same way. */
const exitClass = {
  [NAV_FORWARD]: 'page-exit-forward',
  [NAV_BACK]: 'page-exit-back',
  default: 'page-fade-out',
}

/**
 * Wraps a route's content so it slides directionally on navigation.
 *
 * `name` should be distinct per route. Route pages render into the same slot of
 * the same layout, so without distinct names React can reconcile the two pages'
 * wrappers as one element that merely updated — which animates as a resize
 * rather than the exit/enter pair a directional slide needs.
 */
export function PageTransition({
  name,
  children,
}: {
  name: string
  children: ReactNode
}) {
  return (
    <ViewTransition name={name} enter={enterClass} exit={exitClass}>
      {children}
    </ViewTransition>
  )
}

