/* ==========================================================================
   View transitions

   Layered so that reduced motion is the floor, not an afterthought:

     1. Base rules use opacity only. Anything that reaches them cross-fades.
     2. `prefers-reduced-motion: no-preference` layers the movement on top —
        the directional slides and the morph's travel.
     3. `prefers-reduced-motion: reduce` neutralises the geometry animation the
        browser applies by default, which is the one piece of motion that
        exists with no CSS of ours at all.

   Because the slides live in (2), a reduced-motion visitor never has a
   transform declared for them in the first place.
   ========================================================================== */

:root {
  --vt-morph-duration: 420ms;
  --vt-slide-duration: 320ms;
  --vt-fade-duration: 200ms;
  --vt-reveal-duration: 260ms;
  /* Custom properties inherit into the ::view-transition pseudo tree, which is
     rooted on this element, so the pseudo-element rules below can read them. */
  --vt-ease: cubic-bezier(0.22, 1, 0.36, 1);
}

/* --- Root snapshot -------------------------------------------------------
   Every element we animate is pulled out of the root snapshot into its own
   group, so `root` is left holding just the page background. Cross-fading it
   would only risk a flash, so hold the outgoing copy hidden and the incoming
   copy opaque. Opacity is set explicitly because switching the animation off
   otherwise leaves both copies at full opacity under the browser's
   `plus-lighter` blending, which reads as a bright flicker. */
::view-transition-old(root) {
  animation: none;
  opacity: 0;
}

::view-transition-new(root) {
  animation: none;
  opacity: 1;
}

/* --- Page transitions: base (motion-free) -------------------------------- */
::view-transition-new(.page-enter-forward),
::view-transition-new(.page-enter-back),
::view-transition-new(.page-fade-in) {
  animation: vt-fade-in var(--vt-fade-duration) ease both;
}

::view-transition-old(.page-exit-forward),
::view-transition-old(.page-exit-back),
::view-transition-old(.page-fade-out) {
  animation: vt-fade-out var(--vt-fade-duration) ease both;
}

/* --- Shared product image ------------------------------------------------
   The group carries the thumbnail -> hero geometry change. The old and new
   snapshots keep the browser's default cross-fade, which is already seamless
   here: `plus-lighter` blending makes two copies of the same colour sum to
   that colour at every point in the fade. Retiming rather than replacing the
   animation keeps that behaviour and stays correct once these blocks become
   real photographs with differing content. */
::view-transition-group(.product-image-morph) {
  /* Lift the morphing image above both page snapshots so it stays visible
     while the outgoing page slides out from under it. */
  z-index: 10;
}

::view-transition-old(.product-image-morph),
::view-transition-new(.product-image-morph) {
  animation-duration: var(--vt-morph-duration);
  animation-timing-function: var(--vt-ease);
}

/* --- Suspense reveal ----------------------------------------------------
   Skeleton and content differ in height, so the group's default geometry
   animation eases between the two boxes while the snapshots cross-fade. */
::view-transition-group(.suspense-reveal) {
  animation-duration: var(--vt-reveal-duration);
  animation-timing-function: var(--vt-ease);
}

::view-transition-old(.suspense-reveal),
::view-transition-new(.suspense-reveal) {
  animation-duration: var(--vt-reveal-duration);
  animation-timing-function: ease;
}

@keyframes vt-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes vt-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

/* --- Motion layer -------------------------------------------------------
   Everything below moves things around, so it is all opt-in. */
@media (prefers-reduced-motion: no-preference) {
  ::view-transition-old(.product-image-morph),
  ::view-transition-new(.product-image-morph) {
    animation-duration: var(--vt-morph-duration);
  }

  ::view-transition-group(.product-image-morph) {
    animation-duration: var(--vt-morph-duration);
    animation-timing-function: var(--vt-ease);
  }

  /* Forward: the new page enters from the right, the old one leaves to the
     left. Back: both reverse. Each animation fades as well as translates, so
     the gap the shared image leaves behind in the outgoing snapshot fades out
     rather than sitting there as a visible hole. */
  ::view-transition-new(.page-enter-forward) {
    animation: vt-slide-in-from-right var(--vt-slide-duration) var(--vt-ease)
      both;
  }

  ::view-transition-old(.page-exit-forward) {
    animation: vt-slide-out-to-left var(--vt-slide-duration) var(--vt-ease) both;
  }

  ::view-transition-new(.page-enter-back) {
    animation: vt-slide-in-from-left var(--vt-slide-duration) var(--vt-ease)
      both;
  }

  ::view-transition-old(.page-exit-back) {
    animation: vt-slide-out-to-right var(--vt-slide-duration) var(--vt-ease)
      both;
  }

  @keyframes vt-slide-in-from-right {
    from {
      opacity: 0;
      transform: translateX(2.5rem);
    }
    to {
      opacity: 1;
      transform: translateX(0);
    }
  }

  @keyframes vt-slide-in-from-left {
    from {
      opacity: 0;
      transform: translateX(-2.5rem);
    }
    to {
      opacity: 1;
      transform: translateX(0);
    }
  }

  @keyframes vt-slide-out-to-left {
    from {
      opacity: 1;
      transform: translateX(0);
    }
    to {
      opacity: 0;
      transform: translateX(-2.5rem);
    }
  }

  @keyframes vt-slide-out-to-right {
    from {
      opacity: 1;
      transform: translateX(0);
    }
    to {
      opacity: 0;
      transform: translateX(2.5rem);
    }
  }
}

/* --- Reduced motion ----------------------------------------------------- */
